def main() -> None:
    out_path = sys.argv[1] if len(sys.argv) > 1 else "/output/entry.png"
    out_dir = os.path.dirname(out_path)
    if out_dir:
        os.makedirs(out_dir, exist_ok=True)
    with open(out_path, "wb") as f:
        f.write(ENTRY_PNG)
    print(f"Wrote {out_path} ({len(ENTRY_PNG)} bytes)")


